    -- Dialog and button strings (WoWPro_Frames.lua).
    ["Resize guide window"] = "Изменить размер окна руководства",
    ["Okay"] = "ОК",
    ["Cancel"] = "Отмена",
    ["Skipping the step |cFFFFFF00%s|r will also cause the following steps to skip:\n|cFFFFFF00%s|r\nIf you wanted to just complete the step, |cffff0000cancel|r this dialog and right-click instead.\n"] = "Пропуск шага |cFFFFFF00%s|r также приведёт к пропуску следующих шагов:\n|cFFFFFF00%s|r\nЕсли вы хотели просто завершить шаг, |cffff0000отмените|r это окно и щёлкните правой кнопкой.\n",
