    -- Recorder step-editor descriptions, part 1.
    ["Check if this is a chat step."] = "Отметьте, если это шаг чата.",
    ["Check if this is a quest completion step NOT involving combat."] = "Отметьте, если это шаг завершения задания БЕЗ боя.",
